{"command": "cd /tmp/sv-13c73fe06953452dabdb9df09e2d6cfa && python3 -c "
from elftools.elf.elffile import ELFFile
from elftools.elf.sections import SymbolTableSection
import bisect

with open('libmonosgen-2.0.so.dwarf', 'rb') as f:
    elf = ELFFile(f)
    for sec in elf.iter_sections():
        if not isinstance(sec, SymbolTableSection): continue
        funcs = []
        for sym in sec.iter_symbols():
            v = sym.entry['st_value']
            s = sym.entry['st_size']
            if sym.entry['st_info']['type'] == 'STT_FUNC' and v > 0 and s > 0x100:
                funcs.append((v, sym.name, s))
        funcs.sort()
        addrs = [f[0] for f in funcs]
        for t in [0x2f4b20, 0x2f4c84]:
            idx = bisect.bisect_right(addrs, t) - 1
            if idx >= 0:
                base, name, size = funcs[idx]
                if t < base + size:
                    print(f'0x{t:x} -> {name}+0x{t-base:x} (base=0x{base:x}, size=0x{size:x})')
"", "description": "Find containing functions by size"}

